package org.jeecg.modules.teaching.service;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.jeecg.common.exception.JeecgBootException;
import org.jeecg.modules.teaching.entity.TeachingScratchAssets;
import java.io.IOException;
import java.util.*;

/** The shapes generated by TeachingScratchAssetsForm and consumed by the Scratch library. */
public final class ScratchAssetValidator {
    private static final ObjectMapper JSON = new ObjectMapper();
    private static final Set<String> IMAGE = fields("name,tags,assetId,dataFormat,md5ext,bitmapResolution,rotationCenterX,rotationCenterY");
    private static final Set<String> SOUND = fields("name,tags,assetId,dataFormat,md5ext,rate,sampleCount,format");
    private static final Set<String> SPRITE = fields("name,tags,isStage,variables,blocks,costumes,sounds");
    private ScratchAssetValidator() { }

    public static int type(Integer type) {
        if (type == null || type < 1 || type > 4) throw invalid();
        return type;
    }

    public static String id(Object id) {
        if (!(id instanceof String) || !((String) id).matches("[A-Za-z0-9_-]{1,40}")) throw invalid();
        return (String) id;
    }

    /** Copy only editable columns; never trust caller IDs, audit fields or deletion flags on create. */
    public static TeachingScratchAssets writable(TeachingScratchAssets input) {
        if (input == null) throw invalid();
        int type = type(input.getAssetType());
        JsonNode data = parse(type, input.getAssetData());
        String name = text(data, "name", 100);
        if (input.getAssetName() != null && !name.equals(input.getAssetName())) throw invalid();
        List<String> keys = new ArrayList<>();
        if (type == 4) for (JsonNode costume : data.get("costumes")) keys.add(costume.get("md5ext").asText());
        else keys.add(data.get("md5ext").asText());
        // Keep old internalapi/asset references and current user-scoped upload keys compatible.
        String supplied = input.getMd5Ext();
        String direct = String.join(",", keys);
        String legacy = keys.stream().map(key -> "internalapi/asset/" + key).collect(java.util.stream.Collectors.joining(","));
        if (supplied != null && !supplied.isEmpty() && !supplied.equals(direct) && !supplied.equals(legacy)) throw invalid();
        String md5 = supplied == null || supplied.isEmpty() ? direct : supplied;
        if (md5.length() > 5000) throw invalid();
        List<String> tags = new ArrayList<>();
        if (data.has("tags")) for (JsonNode tag : data.get("tags")) tags.add(tag.asText());
        String tagList = String.join(",", tags);
        if (tagList.length() > 1000) throw invalid();
        return new TeachingScratchAssets().setAssetType(type).setAssetName(name).setAssetData(data.toString())
                .setMd5Ext(md5).setTags(tagList);
    }

    public static JsonNode parse(int type, String raw) {
        type(type);
        if (raw == null || raw.length() > 262144) throw invalid();
        // Bound nesting/tokens before building a tree; do not interpret Fastjson type metadata.
        try (JsonParser parser = JSON.getFactory().createParser(raw)) {
            int depth = 0, tokens = 0;
            JsonToken token;
            while ((token = parser.nextToken()) != null) {
                if (++tokens > 20000) throw invalid();
                if (token == JsonToken.START_OBJECT || token == JsonToken.START_ARRAY) {
                    if (++depth > 8) throw invalid();
                } else if (token == JsonToken.END_OBJECT || token == JsonToken.END_ARRAY) depth--;
            }
        } catch (IOException exception) { throw invalid(); }
        try (JsonParser parser = JSON.getFactory().createParser(raw)) {
            JsonNode root = JSON.readTree(parser);
            if (root == null || parser.nextToken() != null) throw invalid();
            if (type == 4) sprite(root); else media(root, type == 2);
            return root;
        } catch (IOException exception) { throw invalid(); }
    }

    private static void sprite(JsonNode node) {
        shape(node, SPRITE); text(node, "name", 100); tags(node);
        if (!node.has("isStage") || !node.get("isStage").isBoolean() || node.get("isStage").asBoolean()) throw invalid();
        emptyObject(node, "variables"); emptyObject(node, "blocks");
        JsonNode costumes = node.get("costumes"), sounds = node.get("sounds");
        if (costumes == null || !costumes.isArray() || costumes.size() < 1 || costumes.size() > 99
                || sounds == null || !sounds.isArray() || sounds.size() > 99) throw invalid();
        for (JsonNode costume : costumes) media(costume, false);
        for (JsonNode sound : sounds) media(sound, true);
    }

    private static void media(JsonNode node, boolean sound) {
        shape(node, sound ? SOUND : IMAGE); text(node, "name", 100); tags(node);
        String key = text(node, "md5ext", 256);
        if (!key.matches("[A-Za-z0-9_-]+(?:/[A-Za-z0-9_-]+)*\\.[a-z0-9]+")) throw invalid();
        int split = key.lastIndexOf('.');
        String suffix = key.substring(split + 1), assetId = text(node, "assetId", 256);
        if (!key.substring(0, split).equals(assetId)) throw invalid();
        JsonNode format = node.get("dataFormat");
        if (format == null || !format.isTextual()) throw invalid();
        if (sound) {
            if (!fields("wav,mp3,ogg").contains(suffix)
                    || !(format.asText().equals(suffix) || format.asText().isEmpty() || format.asText().equals("adpcm"))) throw invalid();
            if (node.has("format") && (!node.get("format").isTextual()
                    || !fields(",adpcm").contains(node.get("format").asText()))) throw invalid();
            number(node, "rate", 1, 384000, true); number(node, "sampleCount", 0, 1000000000, true);
        } else {
            if (!fields("svg,png,jpg,jpeg,gif").contains(suffix) || !suffix.equals(format.asText())) throw invalid();
            number(node, "bitmapResolution", 1, 2, true);
            number(node, "rotationCenterX", -1000000, 1000000, false);
            number(node, "rotationCenterY", -1000000, 1000000, false);
        }
    }

    private static void shape(JsonNode node, Set<String> allowed) {
        if (node == null || !node.isObject()) throw invalid();
        Iterator<String> names = node.fieldNames();
        while (names.hasNext()) if (!allowed.contains(names.next())) throw invalid();
    }
    private static void emptyObject(JsonNode node, String key) {
        if (!node.has(key) || !node.get(key).isObject() || node.get(key).size() != 0) throw invalid();
    }
    private static String text(JsonNode node, String key, int max) {
        JsonNode value = node.get(key);
        if (value == null || !value.isTextual() || value.asText().trim().isEmpty() || value.asText().length() > max) throw invalid();
        return value.asText();
    }
    private static void tags(JsonNode node) {
        JsonNode tags = node.get("tags");
        if (tags == null) return;
        if (!tags.isArray() || tags.size() > 50) throw invalid();
        for (JsonNode tag : tags) if (!tag.isTextual() || tag.asText().length() > 100) throw invalid();
    }
    private static void number(JsonNode node, String key, double min, double max, boolean integer) {
        JsonNode value = node.get(key);
        if (value == null || !value.isNumber() || (integer && !value.isIntegralNumber())
                || !Double.isFinite(value.asDouble()) || value.asDouble() < min || value.asDouble() > max) throw invalid();
    }
    private static Set<String> fields(String values) { return new HashSet<>(Arrays.asList(values.split(",", -1))); }
    private static JeecgBootException invalid() { return new JeecgBootException("素材类型或数据格式不正确"); }
}
